begin;
set local role authenticated;
select set_config('request.jwt.claim.sub',public.workspace_owner()::text,true);
do $$declare client uuid;product uuid;account uuid;q uuid;entry uuid;receipt uuid;stage text;before_cash bigint;event_count bigint;denied boolean;payload jsonb;source jsonb;rows jsonb;result jsonb;attachment jsonb;begin
 insert into public.clients(kind,name) values('PF','TESTE TRANSACIONAL NOVEMBRO — NÃO É CLIENTE REAL') returning id into client;
 insert into public.products(name,cost,retail,wholesale) values('TESTE TRANSACIONAL NOVEMBRO — PRODUTO',10,20,20) returning id into product;
 account:=public.save_account(null,'TESTE TRANSACIONAL NOVEMBRO',0,current_date,true);
 foreach stage in array array['production','cutting','personalization','sewing'] loop
  q:=public.create_quote_v3(client,'markup',100,current_date,'TESTE TRANSACIONAL — FINALIZAÇÃO DIRETA',jsonb_build_array(jsonb_build_object('product_id',product,'quantity',5)),'{"entry_percentage":50,"technique":"Silk"}');
  perform public.prepare_receivables(q,current_date,current_date);
  select id into entry from public.fin_entries where quote_id=q and installment=1;
  perform public.settle_entry(entry,account,50,current_date,'Pix · TESTE',gen_random_uuid());
  perform public.update_order(q,stage,current_date,'{"art_approved":true,"technique":"Silk"}','',null);
  denied:=false;begin perform public.complete_order_with_receipt(q,'completed',current_date,'{"art_approved":true}','',null,gen_random_uuid());exception when others then denied:=true;end;
  if not denied or (select quotes.stage from public.quotes where id=q)<>stage then raise exception 'Finalização sem pagamento não foi atômica';end if;
  select id into entry from public.fin_entries where quote_id=q and installment=2;
  perform public.settle_entry(entry,account,50,current_date,'Pix · TESTE',gen_random_uuid());
  select count(*) into before_cash from public.fin_settlements;
  receipt:=public.complete_order_with_receipt(q,'completed',current_date,'{"art_approved":true}','Finalização direta, sem passagem registrada pelas etapas intermediárias.',null,gen_random_uuid());
  payload:=public.receipt_view_data(receipt);
  if payload->'receipt'->>'kind'<>'final' or (payload->'receipt'->'snapshot'->>'remaining')::numeric<>0 or jsonb_array_length(payload->'receipt'->'snapshot'->'payments')<>2 or jsonb_array_length(payload->'receipt'->'snapshot'->'order_history')<3 then raise exception 'Histórico do recibo final incompleto';end if;
  if exists(select 1 from public.quote_events where quote_id=q and next_stage not in (stage,'completed')) then raise exception 'Foram inventadas etapas intermediárias';end if;
  if before_cash<>(select count(*) from public.fin_settlements) then raise exception 'Recibo duplicou caixa';end if;
 end loop;
 foreach stage in array array['copy','share'] loop
  q:=public.create_quote_v3(client,'markup',100,current_date,'TESTE TRANSACIONAL — MENSAGEM PRONTO',jsonb_build_array(jsonb_build_object('product_id',product,'quantity',5)),'{"entry_percentage":50,"technique":"Silk"}');
  perform public.prepare_receivables(q,current_date,current_date);
  select id into entry from public.fin_entries where quote_id=q and installment=1;
  perform public.settle_entry(entry,account,50,current_date,'Pix · TESTE',gen_random_uuid());
  perform public.update_order(q,'ready',current_date,'{"art_approved":true,"technique":"Silk"}','',null);
  select count(*) into event_count from public.quote_events where quote_id=q;
  result:=public.mark_ready_message_action(q,stage,'Olá! Seu pedido de TESTE está pronto.',null);
  if result->>'stage'<>'awaiting_balance' or (select quotes.stage from public.quotes where id=q)<>'awaiting_balance' then raise exception 'Mensagem não moveu o pedido';end if;
  result:=public.mark_ready_message_action(q,stage,'Repetição de TESTE',null);
  if (result->>'changed')::boolean or (select count(*) from public.quote_events where quote_id=q)<>event_count+1 then raise exception 'Repetição duplicou a mudança de etapa';end if;
 end loop;
 denied:=false;begin perform public.update_order(q,'cancelled',current_date,'{"art_approved":true}','',null);exception when others then denied:=true;end;if not denied then raise exception 'Cancelamento sem motivo aceito';end if;
 denied:=false;begin perform public.update_order(q,'suspended',current_date,'{"art_approved":true}','',null);exception when others then denied:=true;end;if not denied then raise exception 'Suspensão sem motivo aceita';end if;
 perform public.update_order(q,'suspended',current_date,'{"art_approved":true}','TESTE: suspenso a pedido do cliente',null);
 source:='{"name":"TESTE","uri":"test:registers-transaction","sheet":"TESTE"}';rows:='[{"name":"FORNECEDOR TESTE TRANSACIONAL NOVEMBRO","kind":"PJ","document":"","phone":"","email":"","address":"","source_row":2}]';
 result:=public.import_register_batch('suppliers',source,rows);if (result->>'inserted')::int<>1 then raise exception 'Fornecedor não importado';end if;
 result:=public.import_register_batch('suppliers',source,rows);if (result->>'inserted')::int<>0 or (result->>'skipped')::int<>1 then raise exception 'Reimportação duplicou fornecedor';end if;
 rows:=jsonb_build_array(jsonb_build_object('name','TESTE TRANSACIONAL NOVEMBRO — PRODUTO','reference','TESTE','cost',999,'retail',999,'wholesale',999,'source_row',2));
 result:=public.import_register_batch('products',source,rows);if (select cost from public.products where id=product)<>10 then raise exception 'Importação substituiu preço atual';end if;
 if public.attachment_access('quote',q,'view') is not true then raise exception 'Mestre não pode ver anexos';end if;
 attachment:=public.reserve_document_attachment('quote',q,'teste.pdf','application/pdf',100);
 denied:=false;begin perform public.finish_document_attachment((attachment->>'id')::uuid);exception when others then denied:=true;end;if not denied then raise exception 'Anexo foi concluído sem arquivo';end if;
 denied:=false;begin perform public.reserve_document_attachment('quote',q,'malicioso.html','text/html',100);exception when others then denied:=true;end;if not denied then raise exception 'Formato executável aceito';end if;
 denied:=false;begin perform public.reserve_document_attachment('quote',q,'grande.pdf','application/pdf',10485761);exception when others then denied:=true;end;if not denied then raise exception 'Limite de anexo ignorado';end if;
 perform public.archive_document_attachment((attachment->>'id')::uuid,true);perform public.archive_document_attachment((attachment->>'id')::uuid,false);
 perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000000',true);
 if public.attachment_access('quote',q,'view') or exists(select 1 from public.document_attachments) or exists(select 1 from public.suppliers) then raise exception 'Acesso a dados sem perfil ativo';end if;
end $$;
reset role;
select 'PASSOU: quatro saltos diretos, quitação e histórico, copiar/compartilhar, idempotência, motivos, importação sem duplicação e anexos privados. Dados de teste revertidos.' as resultado;
rollback;
